import System.Type;
import System.Exception;
import System.ArgumentException;
import java.nio.file.*;
import java.util.*;
class TypeShapedMetadataDefinitionProbe {
 static Type base(String name){Type list=Type.GetType("System.Collections.Generic.List`1"),dict=Type.GetType("System.Collections.Generic.Dictionary`2"),nullable=Type.GetType("System.Nullable`1");return switch(name){case "ListD"->list;case "ListS"->list.MakeGenericType(new Type[]{Type.GetType("System.String")});case "ListI"->list.MakeGenericType(new Type[]{Type.GetType("System.Int32")});case "DictD"->dict;case "DictSI"->dict.MakeGenericType(new Type[]{Type.GetType("System.String"),Type.GetType("System.Int32")});case "NullableD"->nullable;case "NullableI"->nullable.MakeGenericType(new Type[]{Type.GetType("System.Int32")});case "Pnullable"->nullable.GetGenericArguments()[0];case "Plist"->list.GetGenericArguments()[0];default->Type.GetType(name);};}
 static Type shaped(Type t,String shape){return switch(shape){case "none"->t;case "sz"->t.MakeArrayType();case "md1"->t.MakeArrayType(1);case "md2"->t.MakeArrayType(2);case "md3"->t.MakeArrayType(3);case "jagged"->t.MakeArrayType().MakeArrayType();case "ptr"->t.MakePointerType();case "ptrptr"->t.MakePointerType().MakePointerType();case "byref"->t.MakeByRefType();case "arrayptr"->t.MakeArrayType().MakePointerType();case "ptrarray"->t.MakePointerType().MakeArrayType();default->throw new AssertionError(shape);};}
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String token(Object o){return o==null?"~":o.toString();}
 public static void main(String[] args)throws java.lang.Exception{List<Type> types=new ArrayList<>();int calls=0,groups=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);if(p[0].equals("T")){types.add(shaped(base(p[1]),p[2]));continue;}Type left=types.get(Integer.parseInt(p[1]));int rightIndex=Integer.parseInt(p[2]);Type right=rightIndex==types.size()?null:types.get(rightIndex);Boolean same=null;String error="none",message=null,param=null;int hResult=0;try{same=left.HasSameMetadataDefinitionAs(right);}catch(Exception expected){error=expected.getClass().getName();message=expected.get_Message();hResult=expected.get_HResult();if(expected instanceof ArgumentException argument)param=argument.get_ParamName();}Object[] actual={same,error,units(message),hResult,units(param),left.Equals(right)};for(int n=0;n<actual.length;n++){if(!token(actual[n]).equals(p[3+n]))throw new AssertionError(p[1]+"/"+p[2]+" field="+n+" actual="+token(actual[n])+" expected="+p[3+n]);groups++;}calls+=2;}java.lang.System.out.println("PASS shaped definitions calls="+calls+" groups="+groups);}
}
